class InvoiceService:
    def __init__(self, repo):
        self.repo = repo

    def get_invoice(self, invoice_id):
        item = self.repo.find(invoice_id)
        if item is None:
            raise KeyError("invoice not found")
        return item

    def delete_invoice(self, invoice_id):
        self.repo.remove(invoice_id)
        return True

